export const getExportUploadUrl = () => {




  return `/api/upload/export`
}

/**
 * @summary Reprocess an in-memory upload and return a CSV download
 */
export const exportUpload = async (uploadExportRequest: UploadExportRequest, options?: Parameters<typeof customFetch>[1]): Promise<string> => {
    const formData = new FormData();
formData.append(`file`, uploadExportRequest.file);
formData.append(`mapping`, uploadExportRequest.mapping);
formData.append(`kind`, uploadExportRequest.kind);

  return customFetch<string>(getExportUploadUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





export const getExportUploadMutationKey = () => ['exportUpload'] as const;

export const getExportUploadMutationOptions = <TError = ErrorType<ApiError>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof exportUpload>>, TError,ExportUploadMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof exportUpload>>, TError,ExportUploadMutationVariables, TContext> => {

const mutationKey = getExportUploadMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof exportUpload>>, ExportUploadMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  exportUpload(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

